1	#!/usr/bin/env bun
2	// Usage: bun scripts/instance.mjs launch | doctor | cleanup
3	// Env: INKLING_VERIFY_NAME, INKLING_VERIFY_PORT (9333), INKLING_VERIFY_DIR (<tmpdir>/verify-inkling-run).
4	// cleanup stops only the pid launch recorded, after confirming its command line,
5	// then deletes the scratch library. Nothing matches by name.
6	import { spawn, spawnSync } from "node:child_process";
7	import { existsSync, mkdirSync, openSync, readFileSync, rmSync, writeFileSync } from "node:fs";
8	import { tmpdir } from "node:os";
9	import { join } from "node:path";
10	
11	const command = process.argv[2];
12	const name = process.env.INKLING_VERIFY_NAME ?? "default";
13	const port = process.env.INKLING_VERIFY_PORT ?? "9333";
14	const windows = process.platform === "win32";
15	const repo = spawnSync("git", ["rev-parse", "--show-toplevel"], { encoding: "utf8" }).stdout.trim();
16	const run = join(process.env.INKLING_VERIFY_DIR ?? join(tmpdir(), "verify-inkling-run"), name);
17	const library = join(run, "library");
18	const pidFile = join(run, "electron.pid");
19	const logFile = join(run, "electron.log");
20	const electronBin = join(
21	  repo,
22	  "node_modules",
23	  "electron",
24	  "dist",
25	  windows ? "electron.exe" : "electron",
26	);
27	
28	const recordedPid = () => (existsSync(pidFile) ? Number(readFileSync(pidFile, "utf8").trim()) : 0);
29	const alive = (pid) => {
30	  if (!(pid > 0)) return false;
31	  try {
32	    process.kill(pid, 0);
33	    return true;
34	  } catch {
35	    return false;
36	  }
37	};
38	const powershell = (script) =>
39	  spawnSync("powershell", ["-NoProfile", "-NonInteractive", "-Command", script], {
40	    encoding: "utf8",
41	  }).stdout.trim();
42	
43	const commandLine = (pid) =>
44	  windows
45	    ? powershell(`(Get-CimInstance Win32_Process -Filter "ProcessId=${pid}").CommandLine`)
46	    : spawnSync("ps", ["-ww", "-p", String(pid), "-o", "args="], {
47	        encoding: "utf8",
48	      }).stdout.trim();
49	const ownsScratchLibrary = (pid) => alive(pid) && commandLine(pid).includes(library);
50	
51	const portOwner = () =>
52	  windows
53	    ? Number(
54	        powershell(
55	          `(Get-NetTCPConnection -LocalPort ${port} -State Listen -ErrorAction SilentlyContinue | Select-Object -First 1).OwningProcess`,
56	        ),
57	      )
58	    : Number(
59	        /pid=(\d+),/.exec(
60	          spawnSync("ss", ["-H", "-ltnp", `sport = :${port}`], { encoding: "utf8" }).stdout,
61	        )?.[1],
62	      );
63	
64	const appPageListed = async () => {
65	  try {
66	    const response = await fetch(`http://127.0.0.1:${port}/json/list`);
67	    return (await response.text()).includes("app://local/index.html");
68	  } catch {
69	    return false;
70	  }
71	};
72	
73	async function launch() {
74	  if (!existsSync(join(repo, "dist", "index.html"))) {
75	    console.error("dist/ missing: run bun run build:app first");
76	    process.exit(1);
77	  }
78	  if (!existsSync(electronBin)) {
79	    console.error(`electron missing at ${electronBin}: run bun install`);
80	    process.exit(1);
81	  }
82	  if (ownsScratchLibrary(recordedPid())) {
83	    console.error(`instance "${name}" is already running (pid ${recordedPid()})`);
84	    process.exit(1);
85	  }
86	  mkdirSync(run, { recursive: true });
87	  const args = [".", `--remote-debugging-port=${port}`, `--user-data-dir=${library}`];
88	  const log = openSync(logFile, "w");
89	  // Electron-based harnesses (T3 Code, Claude Desktop) export ELECTRON_RUN_AS_NODE, which would
90	  // make this Electron start as plain Node and crash on `import "electron"`.
91	  const { ELECTRON_RUN_AS_NODE: _, ...env } = process.env;
92	  const options = { cwd: repo, env, detached: true, stdio: ["ignore", log, log] };
93	  // Linux without a display needs Xvfb. The inner sh records its own pid, then becomes Electron.
94	  const headless = process.platform === "linux" && !process.env.DISPLAY;
95	  const child = headless
96	    ? spawn(
97	        "xvfb-run",
98	        [
99	          "-a",
100	          "sh",
101	          "-c",
102	          'echo $$ > "$0"; shift; exec "$@"',
103	          pidFile,
104	          electronBin,
105	          "--no-sandbox",
106	          ...args,
107	        ],
108	        options,
109	      )
110	    : spawn(electronBin, args, options);
111	  child.unref();
112	  if (!headless) writeFileSync(pidFile, String(child.pid));
113	
114	  for (let attempt = 0; attempt < 60; attempt++) {
115	    if (await appPageListed()) {
116	      console.log(`ready: pid ${recordedPid() || child.pid}, CDP port ${port}, library ${library}`);
117	      return;
118	    }
119	    await new Promise((resolve) => setTimeout(resolve, 1000));
120	  }
121	  console.error(`app page never listed on port ${port}; see ${logFile}`);
122	  process.exit(1);
123	}
124	
125	async function doctor() {
126	  const pid = recordedPid();
127	  let failed = false;
128	  const check = (label, ok) => {
129	    console.log(`${ok ? "PASS" : "FAIL"} ${label}`);
130	    if (!ok) failed = true;
131	  };
132	  check("pidfile present", pid > 0);
133	  check("electron pid alive", pid > 0 && alive(pid));
134	  check("pid runs our scratch data dir", pid > 0 && ownsScratchLibrary(pid));
135	  check("CDP port owned by our pid", pid > 0 && portOwner() === pid);
136	  check("app page loaded over CDP", await appPageListed());
137	  check("library database exists", existsSync(join(library, "library.sqlite3")));
138	  check("renderer build present", existsSync(join(repo, "dist", "index.html")));
139	  process.exit(failed ? 1 : 0);
140	}
141	
142	async function cleanup() {
143	  const pid = recordedPid();
144	  if (pid && ownsScratchLibrary(pid)) {
145	    if (windows) {
146	      spawnSync("taskkill", ["/PID", String(pid), "/T", "/F"]);
147	    } else {
148	      process.kill(pid, "SIGTERM");
149	      for (let attempt = 0; attempt < 10 && alive(pid); attempt++)
150	        await new Promise((resolve) => setTimeout(resolve, 1000));
151	      if (alive(pid)) process.kill(pid, "SIGKILL");
152	    }
153	    console.log(`stopped electron pid ${pid}`);
154	  } else {
155	    console.log("no live electron owned by this run");
156	  }
157	  // Windows releases the SQLite handle a moment after the process dies, so retry on EBUSY.
158	  for (let attempt = 0; ; attempt++) {
159	    try {
160	      rmSync(library, { recursive: true, force: true });
161	      break;
162	    } catch (error) {
163	      if (error.code !== "EBUSY" || attempt === 20) throw error;
164	      await new Promise((resolve) => setTimeout(resolve, 500));
165	    }
166	  }
167	  rmSync(pidFile, { force: true });
168	  console.log(`removed ${library}`);
169	}
170	
171	const commands = { launch, doctor, cleanup };
172	if (!commands[command]) {
173	  console.error("usage: instance.mjs launch | doctor | cleanup");
174	  process.exit(2);
175	}
176	await commands[command]();
177

1	#!/usr/bin/env bun
2	// Runs a list of UI steps against one inkling instance over CDP and records evidence.
3	// Usage: bun scripts/drive.mjs <cdpPort> <steps.json> <evidenceDir>
4	// Each step is one key: click | clickText | fill | key | wait | expect | shot.
5	// Writes <evidenceDir>/steps.log and <evidenceDir>/console.log; a failed step also writes failure.png.
6	import { appendFileSync, mkdirSync, writeFileSync } from "node:fs";
7	import { join } from "node:path";
8	
9	const [port, stepsFile, evidenceDir] = process.argv.slice(2);
10	if (!port || !stepsFile || !evidenceDir)
11	  throw new Error("usage: drive.mjs <cdpPort> <steps.json> <evidenceDir>");
12	mkdirSync(evidenceDir, { recursive: true });
13	const steps = JSON.parse(await Bun.file(stepsFile).text());
14	
15	const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
16	const page = targets.find(
17	  (target) => target.type === "page" && target.url.startsWith("app://local/"),
18	);
19	if (!page) throw new Error(`no inkling page on CDP port ${port}`);
20	const socket = new WebSocket(page.webSocketDebuggerUrl);
21	await new Promise((resolve, reject) => {
22	  socket.onopen = resolve;
23	  socket.onerror = reject;
24	});
25	
26	let seq = 0;
27	const pending = new Map();
28	const consoleLines = [];
29	socket.onmessage = (event) => {
30	  const msg = JSON.parse(event.data);
31	  if (msg.id && pending.has(msg.id)) {
32	    const { resolve, reject } = pending.get(msg.id);
33	    pending.delete(msg.id);
34	    if (msg.error) reject(new Error(msg.error.message));
35	    else resolve(msg.result);
36	    return;
37	  }
38	  if (msg.method === "Runtime.consoleAPICalled") {
39	    const text = msg.params.args.map((arg) => arg.value ?? arg.description ?? "").join(" ");
40	    consoleLines.push(`[${msg.params.type}] ${text}`);
41	  }
42	  if (msg.method === "Runtime.exceptionThrown") {
43	    const details = msg.params.exceptionDetails;
44	    consoleLines.push(`[exception] ${details.exception?.description ?? details.text}`);
45	  }
46	  if (msg.method === "Log.entryAdded")
47	    consoleLines.push(`[${msg.params.entry.level}] ${msg.params.entry.text}`);
48	};
49	const send = (method, params = {}) =>
50	  new Promise((resolve, reject) => {
51	    const id = ++seq;
52	    pending.set(id, { resolve, reject });
53	    socket.send(JSON.stringify({ id, method, params }));
54	  });
55	await send("Runtime.enable");
56	await send("Log.enable");
57	
58	const evaluate = async (expression) => {
59	  const result = await send("Runtime.evaluate", {
60	    expression,
61	    returnByValue: true,
62	    awaitPromise: true,
63	  });
64	  if (result.exceptionDetails)
65	    throw new Error(result.exceptionDetails.exception?.description ?? result.exceptionDetails.text);
66	  return result.result.value;
67	};
68	const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
69	const poll = async (expression, timeoutMs) => {
70	  const deadline = Date.now() + timeoutMs;
71	  while (Date.now() < deadline) {
72	    if (await evaluate(expression)) return true;
73	    await sleep(200);
74	  }
75	  return false;
76	};
77	const q = (selector) => JSON.stringify(selector);
78	const log = (line) => {
79	  console.log(line);
80	  appendFileSync(join(evidenceDir, "steps.log"), `${line}\n`);
81	};
82	
83	const KEYS = {
84	  Enter: { key: "Enter", code: "Enter", keyCode: 13, text: "\r" },
85	  Escape: { key: "Escape", code: "Escape", keyCode: 27 },
86	  "/": { key: "/", code: "Slash", keyCode: 191, text: "/" },
87	};
88	
89	async function run(step) {
90	  const timeout = step.timeoutMs ?? 8000;
91	  if (step.click) {
92	    const found = await poll(`!!document.querySelector(${q(step.click)})`, timeout);
93	    if (!found) throw new Error(`no element ${step.click}`);
94	    await evaluate(`document.querySelector(${q(step.click)}).click()`);
95	    return;
96	  }
97	  if (step.clickText) {
98	    const { selector, text } = step.clickText;
99	    const clicked = await evaluate(`(() => {
100	      const el = [...document.querySelectorAll(${q(selector)})].find((node) => node.textContent.includes(${q(text)}));
101	      if (!el) return false;
102	      el.click();
103	      return true;
104	    })()`);
105	    if (!clicked) throw new Error(`no ${selector} containing "${text}"`);
106	    return;
107	  }
108	  if (step.fill) {
109	    const focused = await poll(
110	      `(() => { const el = document.querySelector(${q(step.fill)}); if (!el) return false; el.focus(); el.select?.(); return true; })()`,
111	      timeout,
112	    );
113	    if (!focused) throw new Error(`no field ${step.fill}`);
114	    await send("Input.insertText", { text: step.text });
115	    return;
116	  }
117	  if (step.key) {
118	    const def = KEYS[step.key] ?? { key: step.key, code: step.key, text: step.key };
119	    await send("Input.dispatchKeyEvent", {
120	      type: def.text ? "keyDown" : "rawKeyDown",
121	      ...def,
122	      windowsVirtualKeyCode: def.keyCode,
123	    });
124	    await send("Input.dispatchKeyEvent", {
125	      type: "keyUp",
126	      ...def,
127	      windowsVirtualKeyCode: def.keyCode,
128	    });
129	    return;
130	  }
131	  if (step.wait) {
132	    if (!(await poll(`!!document.querySelector(${q(step.wait)})`, timeout)))
133	      throw new Error(`timed out waiting for ${step.wait}`);
134	    return;
135	  }
136	  if (step.expect) {
137	    if (!(await poll(`Boolean(${step.expect})`, timeout)))
138	      throw new Error(`expectation never held: ${step.expect}`);
139	    return;
140	  }
141	  if (step.shot) {
142	    const { data } = await send("Page.captureScreenshot", { format: "png" });
143	    await Bun.write(join(evidenceDir, step.shot), Buffer.from(data, "base64"));
144	    return;
145	  }
146	  throw new Error(`unknown step ${JSON.stringify(step)}`);
147	}
148	
149	let failed = false;
150	for (const [index, step] of steps.entries()) {
151	  const label = step.label ?? JSON.stringify(step).slice(0, 120);
152	  try {
153	    await run(step);
154	    log(`PASS ${index + 1} ${label}`);
155	  } catch (error) {
156	    log(`FAIL ${index + 1} ${label}: ${error.message}`);
157	    const { data } = await send("Page.captureScreenshot", { format: "png" });
158	    await Bun.write(join(evidenceDir, "failure.png"), Buffer.from(data, "base64"));
159	    failed = true;
160	    break;
161	  }
162	}
163	writeFileSync(join(evidenceDir, "console.log"), `${consoleLines.join("\n")}\n`);
164	socket.close();
165	process.exit(failed ? 1 : 0);
166

